#include "ksStateMultiLoadTask.h"
#include <array>
#include <iostream>
#include <stdexcept>
using T=ks::StateMultiLoadTask;using W=T::Write;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(bool selected:{false,true})for(unsigned seed=0;seed<65536;++seed){T task(selected?T::Entry::Selected:T::Entry::Provided);unsigned reads=0,writes=0,clocks=0,children=0,globalWrites=0,selectionWrites=0,programWrites=0,activeWrites=0,restoredWrites=0;const unsigned storeClocks=seed&3;auto sourceSelection=[&](){return (seed*13+task.selection()*17)&255;};auto global=[&](){return (seed*19+task.sourceGlobalOffset()*23)&255;};auto bank=[&](){return (seed*31+task.part()*37)&255;};auto program=[&](){return (seed*41+task.part()*43)&255;};auto restored=[&](){return (seed*47+task.selection()*53)&255;};
 auto read=[&](T::Read r)->unsigned{++reads;switch(r){case T::Read::Selection:return sourceSelection();case T::Read::GlobalField:return global();case T::Read::PartBank:return bank();case T::Read::PartProgram:return program();case T::Read::VoiceMode:return seed&255;case T::Read::SavedSelection:return restored();}return 0;};auto write=[&](W w,uint32_t value){++writes;switch(w){case W::PreviousMode:case W::PreviousPart:check(value==255,"Mode invalidation differs");break;case W::DirtyState:case W::GateState:case W::BankState:case W::ModeState:check(value==0,"Engine cache reset differs");break;case W::Selection:check(selectionWrites==task.selection()&&value==sourceSelection(),"Saved selection differs");++selectionWrites;break;case W::GlobalField:check(globalWrites==task.globalField()&&value==global()&&task.targetGlobalOffset()==(globalWrites?task.sourceGlobalOffset():84),"Loaded global field differs");++globalWrites;break;case W::ProgramNumber:check(programWrites==task.part()&&value==((bank()<<8)|program()),"Part program number differs");++programWrites;break;case W::ActiveMask:check(activeWrites==task.part()&&value==(1u<<task.part())&&programWrites==task.part()+1,"Single part selection differs");++activeWrites;break;case W::VoiceMode:check(value==(seed&255)&&programWrites==4,"Global voice mode late copy differs");break;case W::RestoredSelection:check(restoredWrites==task.selection()&&value==restored()&&children==9+selected,"Restored selection differs");++restoredWrites;break;}};
 while(!task.complete()){if(task.awaitingChild()){if(selected&&!children)check(task.child()==T::Child::Source,"Multi source request differs");else{const unsigned n=children-selected;if(n<8)check(task.child()==(n&1?T::Child::Part:T::Child::Mode)&&task.part()==n/2,"Per-part mode/load order differs");else check(task.child()==(n==8?T::Child::VoiceMode:n==9?T::Child::RestoreMode:T::Child::Panel),"Final engine/panel order differs");}++children;check(task.resumeChild(),"Multi load child rejected");continue;}const auto c=task.nextClocks(storeClocks),before=reads,stores=writes;check(!task.advanceBefore(c-1,read,write,storeClocks)&&reads==before&&writes==stores,"Multi load early memory access");check(task.advanceBefore(c,read,write,storeClocks)==c,"Multi load admission differs");clocks+=c;}
 const unsigned expected=1273+21*storeClocks+selected*52;if(clocks!=expected){std::cerr<<"selected="<<selected<<" clocks="<<clocks<<" expected="<<expected<<'\n';throw std::runtime_error("Multi load clocks differ");}check(reads==19&&writes==25&&globalWrites==6&&selectionWrites==2&&programWrites==4&&activeWrites==4&&restoredWrites==2&&children==11+selected&&!task.resumeChild(),"Multi load whole lifetime/counts differ");++cases;}
 std::cout<<"PASS: "<<cases<<" whole selected/provided four-part multi loads,late fields/masks/programs,perpart/cache/voice/panel order,restoration and exact deadlines/clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
